{"op":"add","path":"/root","value":"onboarding-wizard"}
{"op":"add","path":"/elements/onboarding-shell","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg","align":"stretch"},"children":["wizard-heading","step-indicator","step-card","wizard-actions"]}}
{"op":"add","path":"/elements/wizard-heading","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["title","intro"]}}
{"op":"add","path":"/elements/title","value":{"type":"Heading","props":{"text":"Set up your account","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/intro","value":{"type":"Text","props":{"text":"Complete these three steps to create your workspace and tailor your experience.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/step-indicator","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"center"},"children":["step-number","step-name","step-count"]}}
{"op":"add","path":"/elements/step-number","value":{"type":"Badge","props":{"text":{"$template":"Step ${/currentStep} of 3"},"variant":"default"},"children":[]}}
{"op":"add","path":"/elements/step-name","value":{"type":"Text","props":{"text":{"$template":"${/stepName}"},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/step-count","value":{"type":"Text","props":{"text":"Account → Preferences → Done","variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/step-card","value":{"type":"Card","props":{"title":"Account details","description":"Enter the information needed to create your account."},"children":["account-panel","preferences-panel","done-panel"]}}
{"op":"add","path":"/elements/account-panel","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"visible":{"$state":"/currentStep","eq":1},"children":["account-email","account-password","account-helper"]}}
{"op":"add","path":"/elements/account-email","value":{"type":"Input","props":{"label":"Work email","placeholder":"you@company.com","type":"email","value":{"$bindState":"/account/email"}},"children":[]}}
{"op":"add","path":"/elements/account-password","value":{"type":"Input","props":{"label":"Password","placeholder":"At least 8 characters","type":"password","value":{"$bindState":"/account/password"}},"children":[]}}
{"op":"add","path":"/elements/account-helper","value":{"type":"Text","props":{"text":"Use a strong password to keep your account secure.","variant":"small"},"children":[]}}
{"op":"add","path":"/elements/preferences-panel","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"visible":{"$state":"/currentStep","eq":2},"children":["preferences-title","timezone","weekly-digest","notifications","preferences-helper"]}}
{"op":"add","path":"/elements/preferences-title","value":{"type":"Heading","props":{"text":"Choose your preferences","level":"h3"},"children":[]}}
{"op":"add","path":"/elements/timezone","value":{"type":"Select","props":{"label":"Time zone","placeholder":"Select a time zone","options":["Pacific Time (UTC−08:00)","Eastern Time (UTC−05:00)","GMT (UTC+00:00)","Central European Time (UTC+01:00)"],"value":{"$bindState":"/preferences/timezone"}},"children":[]}}
{"op":"add","path":"/elements/weekly-digest","value":{"type":"Switch","props":{"label":"Weekly activity digest","description":"Receive a weekly summary of your account activity.","checked":{"$bindState":"/preferences/weeklyDigest"}},"children":[]}}
{"op":"add","path":"/elements/notifications","value":{"type":"Checkbox","props":{"label":"Send me product updates and recommendations","checked":{"$bindState":"/preferences/productUpdates"}},"children":[]}}
{"op":"add","path":"/elements/preferences-helper","value":{"type":"Text","props":{"text":"You can change these preferences at any time in Settings.","variant":"small"},"children":[]}}
{"op":"add","path":"/elements/done-panel","value":{"type":"Stack","props":{"direction":"vertical","gap":"md","align":"center"},"visible":{"$state":"/currentStep","eq":3},"children":["done-icon","done-title","done-copy","done-email"]}}
{"op":"add","path":"/elements/done-icon","value":{"type":"Badge","props":{"text":"✓ Account ready","variant":"default"},"children":[]}}
{"op":"add","path":"/elements/done-title","value":{"type":"Heading","props":{"text":"You're all set!","level":"h3"},"children":[]}}
{"op":"add","path":"/elements/done-copy","value":{"type":"Text","props":{"text":"Your workspace has been configured according to your preferences.","variant":"body"},"children":[]}}
{"op":"add","path":"/elements/done-email","value":{"type":"Text","props":{"text":{"$template":"Account: ${/account/email}"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/wizard-actions","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"center"},"children":["back-button","next-button","done-button"]}}
{"op":"add","path":"/elements/back-button","value":{"type":"Button","props":{"label":"Back","variant":"secondary","size":"default"},"visible":{"$state":"/currentStep","gt":1},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":2}}},"children":[]}}
{"op":"add","path":"/elements/next-button","value":{"type":"Button","props":{"label":"Next","variant":"default","size":"default"},"visible":{"$state":"/currentStep","lt":3},"on":{"press":{"action":"setState","params":{"statePath":"/currentStep","value":2}}},"children":[]}}
{"op":"add","path":"/elements/done-button","value":{"type":"Button","props":{"label":"Finish setup","variant":"default","size":"default"},"visible":{"$state":"/currentStep","eq":3},"on":{"press":{"action":"setState","params":{"statePath":"/completed","value":true}}},"children":[]}}
{"op":"add","path":"/state/currentStep","value":1}
{"op":"add","path":"/state/stepName","value":"Account"}
